export interface ExtraProduct {
  key: string;
  slug: string;
  name: T3;
  brand: string;
  cat: string;
  type?: "PHYSICAL" | "SPARE_PART" | "CONSUMABLE" | "BUNDLE";
  unit?: string;
  image: string;
  tone: string;
  price: number;
  attrs?: Record<string, string>;
  /** [SKU, variant atributları, qiymət] */
  variants?: [string, Record<string, string>, number][];
  sku?: string;
  conv?: [string, number, number?][];
  warranty?: number;
  rating?: number;
  reviews?: number;
  isNew?: boolean;
  install?: string;
  compat?: string[];
  model?: string;
  pro?: boolean;
  bulky?: boolean;
  cut?: boolean;
  hl?: T3[];
}

const P = (key: string, slug: string, name: T3, brand: string, cat: string, image: string, tone: string, price: number, extra: Partial<ExtraProduct> = {}): ExtraProduct => ({ key, slug, name, brand, cat, image, tone, price, ...extra });
const acV = (base: string, list: [string, number][]) => list.map(([btu, price]) => [`${base}-${btu.slice(0, 2)}`, { cooling_btu: btu }, price] as [string, Record<string, string>, number]);
